/**
 * Generates 8 on-brand illustrated hero images (1920x1080) for the free
 * Minecraft plugin-based game modes. Pure geometric/gradient SVG, rasterized
 * to JPEG via sharp — no external assets, no Minecraft screenshots/footage.
 *
 * Palette matches app/globals.css @theme exactly:
 *   navy-950 #060a14, navy-900 #0a101f, navy-850 #0d1526, navy-800 #111a30,
 *   navy-700 #1a2540, navy-600 #253354, brand-500 #6f47f5, brand-400 #8a70fb,
 *   brand-300 #a89aff, accent-blue #3b82f6, accent-cyan #22d3ee.
 *
 * Background is a static rendering of the same "living infrastructure"
 * constellation motif used by components/marketing/AmbientField.tsx (drifting
 * dots + near-neighbour links), so the set reads as one on-brand family with
 * the rest of the marketing site, not a one-off illustration style.
 */
const path = require("path");
const fs = require("fs");
const sharp = require(path.join("/opt/nxeon-wt-modehero/node_modules/sharp"));

const W = 1920, H = 1080;
const OUT_DIR = "/opt/nxeon-wt-modehero/public/games/art";

const PALETTE = {
  navy950: "#060a14",
  navy900: "#0a101f",
  navy850: "#0d1526",
  navy800: "#111a30",
  navy700: "#1a2540",
  navy600: "#253354",
  brand500: "#6f47f5",
  brand400: "#8a70fb",
  brand300: "#a89aff",
  blue: "#3b82f6",
  cyan: "#22d3ee",
};

// ---------------------------------------------------------------------------
// Deterministic PRNG (mulberry32) so re-running the script for a tweak
// reproduces the exact same constellation field per seed.
function mulberry32(seed) {
  let a = seed;
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Static constellation field: drifting dots + near-neighbour links, same
 *  visual language as AmbientField.tsx's live canvas, baked as one frame. */
function constellation(seed, count = 90) {
  const rnd = mulberry32(seed);
  const pts = Array.from({ length: count }, () => ({ x: rnd() * W, y: rnd() * H }));
  let links = "";
  for (let i = 0; i < pts.length; i++) {
    for (let j = i + 1; j < pts.length; j++) {
      const d = Math.hypot(pts[i].x - pts[j].x, pts[i].y - pts[j].y);
      if (d < 130) {
        const o = (0.14 * (1 - d / 130)).toFixed(3);
        links += `<line x1="${pts[i].x.toFixed(1)}" y1="${pts[i].y.toFixed(1)}" x2="${pts[j].x.toFixed(1)}" y2="${pts[j].y.toFixed(1)}" stroke="#5a6ec8" stroke-opacity="${o}" stroke-width="1"/>`;
      }
    }
  }
  const dots = pts
    .map((p) => `<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="1.6" fill="#7890e0" fill-opacity="0.45"/>`)
    .join("");
  return `<g>${links}${dots}</g>`;
}

/** Shared base: navy gradient wash + two brand radial blooms (matches the
 *  marketing hero's `radial-gradient(ellipse ... rgba(111,71,245,.14))` /
 *  `rgba(59,130,246,.10)` accents) + the constellation field. */
function baseLayer(seed) {
  return `
    <defs>
      <linearGradient id="bg" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${PALETTE.navy950}"/>
        <stop offset="55%" stop-color="${PALETTE.navy900}"/>
        <stop offset="100%" stop-color="${PALETTE.navy850}"/>
      </linearGradient>
      <radialGradient id="bloomViolet" cx="18%" cy="8%" r="55%">
        <stop offset="0%" stop-color="${PALETTE.brand500}" stop-opacity="0.22"/>
        <stop offset="60%" stop-color="${PALETTE.brand500}" stop-opacity="0"/>
      </radialGradient>
      <radialGradient id="bloomBlue" cx="92%" cy="4%" r="55%">
        <stop offset="0%" stop-color="${PALETTE.blue}" stop-opacity="0.16"/>
        <stop offset="60%" stop-color="${PALETTE.blue}" stop-opacity="0"/>
      </radialGradient>
    </defs>
    <rect width="${W}" height="${H}" fill="url(#bg)"/>
    <rect width="${W}" height="${H}" fill="url(#bloomViolet)"/>
    <rect width="${W}" height="${H}" fill="url(#bloomBlue)"/>
    ${constellation(seed)}
  `;
}

/** Soft vignette on top of the motif so the frame edges stay dark/clean and
 *  any UI text overlaid on a card never fights the art for contrast. */
function vignette() {
  return `
    <defs>
      <radialGradient id="vig" cx="50%" cy="50%" r="75%">
        <stop offset="55%" stop-color="#000000" stop-opacity="0"/>
        <stop offset="100%" stop-color="#000000" stop-opacity="0.38"/>
      </radialGradient>
    </defs>
    <rect width="${W}" height="${H}" fill="url(#vig)"/>
  `;
}

function wrap(defsAndBody) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${defsAndBody}</svg>`;
}

// ---------------------------------------------------------------------------
// Per-mode motifs. Each returns the foreground SVG markup only (defs use a
// unique id prefix per mode to avoid collisions if ever inlined together).

function skyblockMotif() {
  // A cluster of floating island chunks (isometric-ish blocky silhouettes)
  // with a tree on top of the largest, drifting embers, glow underneath.
  const cx = W * 0.52, cy = H * 0.52;
  function island(x, y, s, op) {
    return `
      <g transform="translate(${x} ${y}) scale(${s})" opacity="${op}">
        <ellipse cx="0" cy="46" rx="150" ry="26" fill="url(#skyGlow)"/>
        <polygon points="-120,-10 0,-70 120,-10 0,50" fill="url(#skyTop)"/>
        <polygon points="-120,-10 0,50 -60,90 -120,40" fill="url(#skySideL)"/>
        <polygon points="120,-10 0,50 60,90 120,40" fill="url(#skySideR)"/>
      </g>`;
  }
  return `
    <defs>
      <linearGradient id="skyTop" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${PALETTE.brand300}"/>
        <stop offset="100%" stop-color="${PALETTE.brand500}"/>
      </linearGradient>
      <linearGradient id="skySideL" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${PALETTE.navy700}"/>
        <stop offset="100%" stop-color="${PALETTE.navy850}"/>
      </linearGradient>
      <linearGradient id="skySideR" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${PALETTE.navy600}"/>
        <stop offset="100%" stop-color="${PALETTE.navy800}"/>
      </linearGradient>
      <radialGradient id="skyGlow" cx="50%" cy="50%" r="50%">
        <stop offset="0%" stop-color="${PALETTE.cyan}" stop-opacity="0.35"/>
        <stop offset="100%" stop-color="${PALETTE.cyan}" stop-opacity="0"/>
      </radialGradient>
    </defs>
    ${island(cx - 430, cy - 120, 0.55, 0.85)}
    ${island(cx + 470, cy + 40, 0.62, 0.85)}
    ${island(cx, cy, 1, 1)}
    <g transform="translate(${cx} ${cy - 70})">
      <rect x="-14" y="-70" width="28" height="70" fill="#5b3a26"/>
      <circle cx="0" cy="-95" r="55" fill="${PALETTE.cyan}" fill-opacity="0.5"/>
      <circle cx="-40" cy="-70" r="38" fill="${PALETTE.cyan}" fill-opacity="0.4"/>
      <circle cx="42" cy="-75" r="40" fill="${PALETTE.cyan}" fill-opacity="0.4"/>
    </g>
    <rect x="${cx - 20}" y="${cy - 10}" width="40" height="30" fill="#7a5230"/>
  `;
}

function prisonMotif() {
  const cx = W * 0.52, cy = H * 0.54;
  let bars = "";
  for (let i = -5; i <= 5; i++) {
    bars += `<rect x="${cx + i * 46 - 6}" y="${cy - 260}" width="12" height="520" rx="4" fill="url(#barGrad)"/>`;
  }
  return `
    <defs>
      <linearGradient id="barGrad" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${PALETTE.navy600}"/>
        <stop offset="50%" stop-color="#3a4a72"/>
        <stop offset="100%" stop-color="${PALETTE.navy700}"/>
      </linearGradient>
      <radialGradient id="prisonGlow" cx="50%" cy="35%" r="60%">
        <stop offset="0%" stop-color="${PALETTE.cyan}" stop-opacity="0.28"/>
        <stop offset="100%" stop-color="${PALETTE.cyan}" stop-opacity="0"/>
      </radialGradient>
      <linearGradient id="cartGrad" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${PALETTE.brand400}"/>
        <stop offset="100%" stop-color="${PALETTE.brand500}"/>
      </linearGradient>
    </defs>
    <rect width="${W}" height="${H}" fill="url(#prisonGlow)"/>
    <!-- pickaxe glint rays -->
    <g opacity="0.5" stroke="${PALETTE.cyan}" stroke-width="3">
      <line x1="${cx - 260}" y1="${cy + 260}" x2="${cx - 90}" y2="${cy + 150}"/>
      <line x1="${cx - 200}" y1="${cy + 300}" x2="${cx - 60}" y2="${cy + 190}"/>
    </g>
    <!-- mine cart -->
    <g transform="translate(${cx - 30} ${cy + 190})">
      <rect x="-90" y="-40" width="180" height="70" rx="10" fill="url(#cartGrad)"/>
      <rect x="-70" y="-60" width="140" height="24" rx="6" fill="${PALETTE.navy700}"/>
      <circle cx="-50" cy="40" r="24" fill="${PALETTE.navy800}" stroke="${PALETTE.brand300}" stroke-width="4"/>
      <circle cx="50" cy="40" r="24" fill="${PALETTE.navy800}" stroke="${PALETTE.brand300}" stroke-width="4"/>
      <polygon points="60,-30 130,-90 150,-70 90,-10" fill="#c9c2ff"/>
    </g>
    ${bars}
  `;
}

function townyMotif() {
  const cx = W * 0.52, base = H * 0.72;
  function house(x, s, hue) {
    return `
      <g transform="translate(${x} ${base}) scale(${s})">
        <rect x="-70" y="-100" width="140" height="100" fill="${hue}"/>
        <polygon points="-90,-100 0,-170 90,-100" fill="url(#roofGrad)"/>
        <rect x="-16" y="-60" width="32" height="60" fill="${PALETTE.navy900}"/>
        <rect x="-52" y="-70" width="26" height="26" fill="${PALETTE.cyan}" fill-opacity="0.75"/>
        <rect x="26" y="-70" width="26" height="26" fill="${PALETTE.cyan}" fill-opacity="0.75"/>
      </g>`;
  }
  return `
    <defs>
      <linearGradient id="roofGrad" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${PALETTE.brand300}"/>
        <stop offset="100%" stop-color="${PALETTE.brand500}"/>
      </linearGradient>
      <radialGradient id="townGlow" cx="50%" cy="60%" r="55%">
        <stop offset="0%" stop-color="${PALETTE.brand500}" stop-opacity="0.22"/>
        <stop offset="100%" stop-color="${PALETTE.brand500}" stop-opacity="0"/>
      </radialGradient>
    </defs>
    <rect width="${W}" height="${H}" fill="url(#townGlow)"/>
    ${house(cx - 320, 0.85, PALETTE.navy700)}
    ${house(cx + 300, 0.9, PALETTE.navy700)}
    ${house(cx, 1.25, PALETTE.navy600)}
    <!-- banner pole -->
    <g transform="translate(${cx} ${base - 210})">
      <rect x="-6" y="0" width="12" height="180" fill="#5b3a26"/>
      <polygon points="6,0 130,26 6,52" fill="url(#roofGrad)"/>
    </g>
    <rect x="0" y="${base + 2}" width="${W}" height="${H - base}" fill="${PALETTE.navy950}" fill-opacity="0.7"/>
  `;
}

function parkourMotif() {
  const baseY = H * 0.66;
  let tiles = "";
  const steps = 7;
  for (let i = 0; i < steps; i++) {
    const x = 260 + i * 205;
    const y = baseY - Math.sin(i * 0.9) * 70 - i * 18;
    const lit = i % 2 === 0;
    tiles += `<g transform="translate(${x} ${y})">
        <polygon points="-70,0 0,-30 70,0 0,30" fill="${lit ? "url(#tileLit)" : "url(#tileDim)"}"/>
        <ellipse cx="0" cy="46" rx="60" ry="14" fill="${PALETTE.cyan}" fill-opacity="0.12"/>
      </g>`;
  }
  // dashed jump arc trail
  let arc = "";
  for (let i = 0; i < steps - 1; i++) {
    const x1 = 260 + i * 205, y1 = baseY - Math.sin(i * 0.9) * 70 - i * 18 - 34;
    const x2 = 260 + (i + 1) * 205, y2 = baseY - Math.sin((i + 1) * 0.9) * 70 - (i + 1) * 18 - 34;
    const mx = (x1 + x2) / 2, my = Math.min(y1, y2) - 60;
    arc += `<path d="M ${x1} ${y1} Q ${mx} ${my} ${x2} ${y2}" stroke="${PALETTE.cyan}" stroke-opacity="0.55" stroke-width="3" stroke-dasharray="2 12" stroke-linecap="round" fill="none"/>`;
  }
  return `
    <defs>
      <linearGradient id="tileLit" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${PALETTE.brand300}"/>
        <stop offset="100%" stop-color="${PALETTE.brand500}"/>
      </linearGradient>
      <linearGradient id="tileDim" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${PALETTE.navy600}"/>
        <stop offset="100%" stop-color="${PALETTE.navy800}"/>
      </linearGradient>
    </defs>
    ${arc}
    ${tiles}
  `;
}

function anarchyMotif() {
  const cx = W * 0.52, cy = H * 0.5;
  const rnd = mulberry32(777);
  let cracks = "";
  for (let i = 0; i < 9; i++) {
    const a = rnd() * Math.PI * 2;
    const len = 220 + rnd() * 340;
    let x = cx, y = cy, ang = a;
    let d = `M ${x} ${y} `;
    for (let s = 0; s < 4; s++) {
      ang += (rnd() - 0.5) * 0.9;
      x += Math.cos(ang) * (len / 4);
      y += Math.sin(ang) * (len / 4);
      d += `L ${x.toFixed(1)} ${y.toFixed(1)} `;
    }
    cracks += `<path d="${d}" stroke="url(#crackGrad)" stroke-width="${2 + rnd() * 3}" fill="none" stroke-linecap="round"/>`;
  }
  return `
    <defs>
      <linearGradient id="crackGrad" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" stop-color="${PALETTE.cyan}"/>
        <stop offset="100%" stop-color="#f97066"/>
      </linearGradient>
      <radialGradient id="anarchyGlow" cx="50%" cy="50%" r="45%">
        <stop offset="0%" stop-color="#f97066" stop-opacity="0.18"/>
        <stop offset="100%" stop-color="#f97066" stop-opacity="0"/>
      </radialGradient>
    </defs>
    <rect width="${W}" height="${H}" fill="url(#anarchyGlow)"/>
    <polygon points="${cx},${cy - 8} ${cx + 8},${cy} ${cx},${cy + 8} ${cx - 8},${cy}" fill="#f97066"/>
    ${cracks}
  `;
}

function lifestealMotif() {
  const cx = W * 0.52, cy = H * 0.52;
  function heart(x, y, s, op) {
    return `<path transform="translate(${x} ${y}) scale(${s})"
      d="M0,34 C-70,-14 -70,-64 -28,-64 C-8,-64 0,-46 0,-34 C0,-46 8,-64 28,-64 C70,-64 70,-14 0,34 Z"
      fill="url(#heartGrad)" opacity="${op}"/>`;
  }
  return `
    <defs>
      <linearGradient id="heartGrad" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${PALETTE.brand300}"/>
        <stop offset="55%" stop-color="${PALETTE.brand500}"/>
        <stop offset="100%" stop-color="#b0296e"/>
      </linearGradient>
      <radialGradient id="lifestealGlow" cx="50%" cy="50%" r="50%">
        <stop offset="0%" stop-color="${PALETTE.brand400}" stop-opacity="0.4"/>
        <stop offset="100%" stop-color="${PALETTE.brand400}" stop-opacity="0"/>
      </radialGradient>
    </defs>
    <rect width="${W}" height="${H}" fill="url(#lifestealGlow)"/>
    ${heart(cx - 480, cy - 220, 0.55, 0.5)}
    ${heart(cx + 500, cy + 180, 0.6, 0.5)}
    ${heart(cx - 420, cy + 260, 0.4, 0.4)}
    ${heart(cx, cy, 3.1, 1)}
  `;
}

function missilewarsMotif() {
  const cx = W * 0.5, cy = H * 0.5;
  function missile(x, y, rot, s, op) {
    return `
      <g transform="translate(${x} ${y}) rotate(${rot}) scale(${s})" opacity="${op}">
        <rect x="-260" y="-14" width="260" height="28" rx="14" fill="${PALETTE.cyan}" fill-opacity="0.55"/>
        <polygon points="0,-26 60,0 0,26" fill="url(#missileGrad)"/>
        <polygon points="-14,-24 -50,-56 -50,-8" fill="${PALETTE.navy700}"/>
        <polygon points="-14,24 -50,56 -50,8" fill="${PALETTE.navy700}"/>
      </g>`;
  }
  return `
    <defs>
      <linearGradient id="missileGrad" x1="0" y1="0" x2="1" y2="0">
        <stop offset="0%" stop-color="${PALETTE.brand400}"/>
        <stop offset="100%" stop-color="${PALETTE.brand300}"/>
      </linearGradient>
      <radialGradient id="burst" cx="50%" cy="50%" r="50%">
        <stop offset="0%" stop-color="${PALETTE.cyan}" stop-opacity="0.5"/>
        <stop offset="60%" stop-color="${PALETTE.brand500}" stop-opacity="0.15"/>
        <stop offset="100%" stop-color="${PALETTE.brand500}" stop-opacity="0"/>
      </radialGradient>
    </defs>
    <circle cx="${cx + 260}" cy="${cy - 60}" r="260" fill="url(#burst)"/>
    <!-- arena platform -->
    <polygon points="${cx - 520},${cy + 240} ${cx + 520},${cy + 240} ${cx + 300},${cy + 340} ${cx - 300},${cy + 340}"
      fill="${PALETTE.navy700}" fill-opacity="0.8"/>
    <polygon points="${cx - 520},${cy + 240} ${cx + 520},${cy + 240} ${cx + 470},${cy + 210} ${cx - 470},${cy + 210}"
      fill="${PALETTE.navy600}"/>
    ${missile(cx - 60, cy - 20, -18, 1, 1)}
    ${missile(cx - 520, cy + 260, -10, 0.42, 0.5)}
  `;
}

function survivalgamesMotif() {
  const cx = W * 0.52, cy = H * 0.5;
  let spokes = "";
  const n = 14;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const x2 = cx + Math.cos(a) * 480, y2 = cy + Math.sin(a) * 270;
    spokes += `<line x1="${cx}" y1="${cy}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" stroke="${PALETTE.brand400}" stroke-opacity="0.18" stroke-width="2"/>`;
  }
  return `
    <defs>
      <radialGradient id="arenaGlow" cx="50%" cy="50%" r="55%">
        <stop offset="0%" stop-color="${PALETTE.cyan}" stop-opacity="0.3"/>
        <stop offset="70%" stop-color="${PALETTE.brand500}" stop-opacity="0.12"/>
        <stop offset="100%" stop-color="${PALETTE.brand500}" stop-opacity="0"/>
      </radialGradient>
      <linearGradient id="ringGrad" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${PALETTE.brand300}"/>
        <stop offset="100%" stop-color="${PALETTE.brand500}"/>
      </linearGradient>
    </defs>
    <rect width="${W}" height="${H}" fill="url(#arenaGlow)"/>
    ${spokes}
    <ellipse cx="${cx}" cy="${cy}" rx="480" ry="270" fill="none" stroke="url(#ringGrad)" stroke-width="10"/>
    <ellipse cx="${cx}" cy="${cy}" rx="360" ry="200" fill="none" stroke="${PALETTE.cyan}" stroke-opacity="0.5" stroke-width="4" stroke-dasharray="6 14"/>
    <!-- last-one-standing beacon at center -->
    <g transform="translate(${cx} ${cy})">
      <rect x="-8" y="-140" width="16" height="140" fill="url(#ringGrad)"/>
      <circle cx="0" cy="-150" r="22" fill="${PALETTE.cyan}" fill-opacity="0.85"/>
      <circle cx="0" cy="-150" r="46" fill="${PALETTE.cyan}" fill-opacity="0.25"/>
    </g>
  `;
}

const MODES = {
  skyblock: skyblockMotif,
  prison: prisonMotif,
  towny: townyMotif,
  parkour: parkourMotif,
  anarchy: anarchyMotif,
  lifesteal: lifestealMotif,
  missilewars: missilewarsMotif,
  survivalgames: survivalgamesMotif,
};

async function main() {
  fs.mkdirSync(OUT_DIR, { recursive: true });
  let seed = 1000;
  for (const [key, motifFn] of Object.entries(MODES)) {
    seed += 37;
    const svg = wrap(baseLayer(seed) + motifFn() + vignette());
    const outPath = path.join(OUT_DIR, `freemc-${key}_hero.jpg`);
    await sharp(Buffer.from(svg), { density: 144 })
      .resize(W, H)
      .jpeg({ quality: 90, mozjpeg: true })
      .toFile(outPath);
    console.log("wrote", outPath);
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

