"use client";

import { useState } from "react";
import { GAME_VISUAL } from "@/components/marketing/GameLogo";
import { GAME_ART_SLUG, type GameFamily } from "@/lib/games";

/**
 * GameCoverTile — a compact portrait "box-art" cover, the small-scale version of
 * the /game-servers hero carousel cover, for use in pickers (e.g. the game deploy
 * wizard). Resolution chain (first that loads wins):
 *
 *   public/games/art/<artSlug>_poster.jpg                ← real portrait key-art
 *   public/logos/games/covers/<family>.{webp,jpg,png}    ← owner cover drop-in
 *   public/logos/games/<family>.png                      ← wordmark fallback
 *   per-game gradient                                     ← final fallback
 *
 * Plain <img> so the onError chain advances client-side. Aspect ~2:3 (poster).
 */
export function GameCoverTile({ family, name }: { family: string; name: string }) {
  const visual = GAME_VISUAL[family] ?? { name, glyph: "🎮", from: "#334155", to: "#64748b" };
  const artSlug = GAME_ART_SLUG[family as GameFamily]?.poster;
  const chain = [
    ...(artSlug ? [`/games/art/${artSlug}_poster.jpg`] : []),
    `/logos/games/covers/${family}.webp`,
    `/logos/games/covers/${family}.jpg`,
    `/logos/games/covers/${family}.png`,
    `/logos/games/${family}.png`, // wordmark fallback (not full art)
  ];
  const [idx, setIdx] = useState(0);
  const exhausted = idx >= chain.length;
  const isWordmark = idx === chain.length - 1;

  return (
    <div
      className="relative aspect-[2/3] w-full overflow-hidden rounded-lg"
      style={{ background: `radial-gradient(130% 100% at 50% 0%, ${visual.from}, ${visual.to})` }}
    >
      {!exhausted && (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={chain[idx]}
          alt={name}
          className={isWordmark ? "absolute inset-0 m-auto h-1/2 w-auto object-contain drop-shadow" : "absolute inset-0 h-full w-full object-cover"}
          onError={() => setIdx((i) => i + 1)}
        />
      )}
      {exhausted && (
        <span className="absolute inset-0 flex items-center justify-center text-2xl" aria-hidden>
          {visual.glyph}
        </span>
      )}
      {/* bottom vignette so a name overlaid by the parent stays legible on any art */}
      <div className="pointer-events-none absolute inset-x-0 bottom-0 h-1/3 bg-gradient-to-t from-black/70 to-transparent" />
    </div>
  );
}

